import subprocess

def get_memory_status():
    try:
        result = subprocess.run(['powershell', '-NoProfile', '-NonInteractive', '-Command', 'Get-WmiObject -Class Win32_OperatingSystem | Select-Object -Property FreePhysicalMemory,TotalVisibleMemorySize'],
                                capture_output=True, text=True)
        if result.returncode == 0:
            memory_info = result.stdout.splitlines()
            free_memory = int(memory_info[1].split()[1])
            total_memory = int(memory_info[1].split()[3])
            memory_usage = round((1 - (free_memory / total_memory)) * 100, 2)
            return {'status': memory_usage}
        else:
            return {'status': '未実装'}
    except Exception as e:
        return {'status': '未実装'}
